DnsEvents
| where TimeGenerated > ago(90d) 
| where SubType == "LookupQuery"
| where ClientIP == "10.10.10.10" // Replace top ClientIP from Query 1
| where strlen(Name) > DNSHostnameLengthCheck
| distinct Name

