       ProofPointFeed 
       | where DestIP matches regex IPRegex
       | distinct DestIP
        );
let MaliciousIP6 = materialize (
       FeodoFeed 
       | extend IP = extract(IPRegex, 0, Row)
       | where isnotempty(IP)
       | distinct IP
        );
