       DiamondFoxFeed 
       | extend DomainOrIP = extract(@'//(.*?)/', 1, Row)
       | extend DomainOrIPToLower = tolower(DomainOrIP)
       | where DomainOrIPToLower matches regex IPRegex
       | distinct DomainOrIP
        );
